package com.aistock.scheduler.adminrefresh;
import com.aistock.common.*;import com.aistock.common.adminrefresh.AdminMarketRefreshRecords.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.scheduler.adminrefresh.RefreshTestDb.*;
class AdminMarketRefreshServiceTest {
 @Test void knownSubmissionReplaysWithoutMarketCall(){var repo=mock(AdminMarketRefreshRepository.class);var cmd=command();var receipt=new Receipt(cmd.operationId().toString(),"SH600030",ACTOR.toString(),"REJECTED","REFRESH_COOLDOWN",null,VERSION,"7",null,cmd.targetDate(),cmd.reasonCode(),NOW,NOW,true);var expected=new Submission(409,"REFRESH_COOLDOWN",receipt);when(repo.existing(ACTOR,"SH600030",cmd)).thenReturn(expected);var service=new AdminMarketRefreshService(repo,(id,token)->{throw new AssertionError("must not precheck replay");},"fixture");assertEquals(expected,service.submit(ACTOR,"SH600030",cmd,NOW));}
 @Test void upstreamFailureDoesNotInventReceipt(){var repo=mock(AdminMarketRefreshRepository.class);var service=new AdminMarketRefreshService(repo,(id,token)->{throw new IllegalStateException("fixture unavailable");},"fixture");assertEquals("MARKET_ADMIN_UNAVAILABLE",assertThrows(BusinessException.class,()->service.submit(ACTOR,"SH600030",command(),NOW)).code());verify(repo,never()).submit(any(),any(),any(),any(),any());}
}